/*\
title: $:/plugins/huwiki/ai/manual-connections.js
type: application/javascript
module-type: library

Optional browser-direct AI connections. Keys are only held in this module's
JavaScript memory: never tiddlers, localStorage, sessionStorage or URLs.
Direct cloud requests are experimental, may be rejected by browser CORS rules,
and expose the key to code running in the browser. ForgeShare remains available.
\*/
(function(){
"use strict";
var adapters=require("$:/plugins/huwiki/ai/model-adapters.js");
var aiUi=require("$:/plugins/huwiki/ai/i18n.js");
var secrets=Object.create(null);
var CLOUD={
  openai:{models:"https://api.openai.com/v1/models",chat:"https://api.openai.com/v1/chat/completions"},
  claude:{models:"https://api.anthropic.com/v1/models?limit=100",chat:"https://api.anthropic.com/v1/messages"},
  gemini:{models:"https://generativelanguage.googleapis.com/v1beta/models?pageSize=100",
    chat:"https://generativelanguage.googleapis.com/v1beta/models/"}
};
function tr(da,en){return aiUi.choose(da,en);}
function known(provider){return provider==="ollama"||provider==="lmstudio"||Object.prototype.hasOwnProperty.call(CLOUD,provider);}
function cloud(provider){return Object.prototype.hasOwnProperty.call(CLOUD,provider);}
function setKey(provider,value){
  if(!known(provider))throw Error("Ukendt AI-forbindelse");
  value=String(value||"").trim();
  if(value)secrets[provider]=value;else delete secrets[provider];
}
function getKey(provider){return secrets[provider]||"";}
function forgetKey(provider){delete secrets[provider];}
function requireKey(provider){
  if(cloud(provider)&&!getKey(provider))throw Error(tr("Indtast en API-nøgle til ","Enter an API key for ")+adapters.providerLabel(provider)+".");
}
function secretControl(root,provider){
  if(provider==="ollama"||!known(provider))return null;
  var d=root.ownerDocument,wrap=d.createElement("label"),title=d.createElement("span"),input=d.createElement("input");
  wrap.className="huwiki-ai-field";
  title.className="huwiki-ai-label";
  title.textContent=cloud(provider)?tr("API-nøgle · kun denne session","API key · this session only"):tr("API-nøgle (valgfri) · kun denne session","API key (optional) · this session only");
  input.className="huwiki-ai-input";
  input.type="password";
  input.name="huwiki-ai-key-"+provider;
  input.autocomplete="current-password"; // Allows an explicit password-manager offer; not guaranteed.
  input.spellcheck=false;input.autocapitalize="off";input.autocorrect="off";
  input.value=getKey(provider);
  function capture(){setKey(provider,input.value);}
  input.addEventListener("input",capture);
  input.addEventListener("change",capture);
  input.addEventListener("blur",capture);
  wrap.appendChild(title);wrap.appendChild(input);root.appendChild(wrap);
  var row=d.createElement("div");row.className="huwiki-ai-actions";
  var clear=d.createElement("button");clear.type="button";clear.className="huwiki-ai-button huw-ai-secondary";
  clear.textContent=tr("Glem nøgle","Forget key");
  clear.addEventListener("click",function(){forgetKey(provider);input.value="";input.focus();});
  row.appendChild(clear);root.appendChild(row);
  var note=d.createElement("p");note.className="huwiki-ai-help";
  note.textContent=tr(
    "Nøglen gemmes ikke i wikien eller browserlageret. Chrome kan muligvis tilbyde autofyldning. Direkte browserkald er eksperimentelle: scripts og udvidelser kan se nøglen, og CORS kan blokere.",
    "The key is never saved in the wiki or browser storage. Chrome may offer autofill. Direct browser calls are experimental: scripts and extensions may access the key, and CORS may block requests."
  );root.appendChild(note);
  return input;
}
function headers(provider){
  var h={"Content-Type":"application/json"};
  var key=getKey(provider);
  if(provider==="openai")h.Authorization="Bearer "+key;
  else if(provider==="claude"){
    h["x-api-key"]=key;h["anthropic-version"]="2023-06-01";
    h["anthropic-dangerous-direct-browser-access"]="true";
  } else if(provider==="gemini")h["x-goog-api-key"]=key;
  else if(provider==="lmstudio"&&key)h.Authorization="Bearer "+key;
  return h;
}
function endpoint(provider,url,model,isModels){
  if(cloud(provider)){
    if(isModels)return CLOUD[provider].models;
    if(provider==="gemini"){
      var id=String(model||"").replace(/^models\//,"");
      if(!/^[\w.-]+$/.test(id))throw Error(tr("Ugyldigt Gemini-modelnavn","Invalid Gemini model name"));
      return CLOUD.gemini.chat+encodeURIComponent(id)+":generateContent";
    }
    return CLOUD[provider].chat;
  }
  return isModels?adapters.modelsEndpoint(provider,url):adapters.chatEndpoint(provider,url);
}
function responseError(provider,status){
  var kind=status===401||status===403?tr("kontrollér API-nøgle og adgang","check API key and permissions"):
    status===429?tr("grænse for antal kald eller saldo","rate limit or quota"):
    status===404?tr("kontrollér modelnavn og API-adresse","check model name and API endpoint"):
    tr("kontrollér model, adgang og udbyderens status","check model, permissions and provider status");
  return Error(adapters.providerLabel(provider)+" HTTP "+status+" · "+kind);
}
function requestJson(provider,url,options){
  return fetch(url,options).then(function(r){
    if(!r.ok)throw responseError(provider,r.status);
    return r.json();
  }).catch(function(e){
    if(e && e.name==="TypeError")throw Error(adapters.providerLabel(provider)+
      tr(": Browseren kunne ikke forbinde. Kontrollér netværk, HTTPS og CORS.",": Browser connection failed. Check network, HTTPS and CORS."));
    throw e;
  });
}
function listModels(provider,url){
  if(!known(provider))return Promise.reject(Error("Ukendt AI-motor"));
  try{requireKey(provider);}catch(e){return Promise.reject(e);}
  var target;
  try{target=endpoint(provider,url,"",true);}catch(e){return Promise.reject(e);}
  return requestJson(provider,target,{
    method:"GET",mode:"cors",cache:"no-store",credentials:"omit",redirect:"error",
    headers:headers(provider)
  }).then(function(data){
    var list;
    if(provider==="gemini")list=(data.models||[]).filter(function(x){
      return !x.supportedGenerationMethods||x.supportedGenerationMethods.indexOf("generateContent")>=0;
    }).map(function(x){return String(x.name||"").replace(/^models\//,"");});
    else if(cloud(provider))list=(data.data||[]).map(function(x){return x&&x.id;});
    else return adapters.parseModels(provider,data);
    if(!Array.isArray(list))throw Error(tr("Ugyldigt svar fra modelserver","Invalid model server response"));
    return list.filter(function(x){return typeof x==="string"&&!!x;}).sort();
  });
}
function imageParts(provider,content,images){
  var parts=[{type:"text",text:String(content||"")}];
  (images||[]).forEach(function(im){
    var mime=String(im.mimeType||"");
    if(!/^image\/(?:png|jpeg|webp)$/.test(mime))throw Error("Unsupported image type");
    if(provider==="openai")parts.push({type:"image_url",image_url:{url:"data:"+mime+";base64,"+im.data}});
    else if(provider==="claude")parts.push({type:"image",source:{type:"base64",media_type:mime,data:im.data}});
    else if(provider==="gemini")parts.push({inline_data:{mime_type:mime,data:im.data}});
  });
  return parts;
}
function cloudRequest(provider,model,messages,kind,images){
  var isChat=kind==="chat",system=messages.filter(function(m){return m.role==="system";})
    .map(function(m){return String(m.content||"");}).join("\n\n");
  var body=messages.filter(function(m){return m.role!=="system";}).map(function(m){
    return {role:m.role==="assistant"?"assistant":"user",content:String(m.content||"")};
  });
  if(!body.length)throw Error(tr("Ingen AI-beskeder at sende","No AI messages to send"));
  var last=-1;for(var i=body.length-1;i>=0;i--)if(body[i].role==="user"){last=i;break;}
  if(images&&images.length&&last<0)throw Error("No user message for image");
  if(provider==="openai"){
    var openaiMessages=system?[{role:"system",content:system}]:[];
    body.forEach(function(m,i){
      openaiMessages.push({role:m.role,content:i===last&&images&&images.length?
        imageParts("openai",m.content,images):m.content});
    });
    return {model:model,messages:openaiMessages,stream:false};
  }
  if(provider==="claude"){
    var claudeBody=body.map(function(m,i){return {role:m.role,content:i===last&&images&&images.length?
      imageParts("claude",m.content,images):m.content};});
    var req={model:model,max_tokens:isChat?2048:2400,messages:claudeBody};
    if(system)req.system=system;
    return req;
  }
  var contents=body.map(function(m,i){
    var parts=[{text:m.content}];
    if(i===last&&images&&images.length)parts=parts.concat(imageParts("gemini","",images).slice(1));
    return {role:m.role==="assistant"?"model":"user",parts:parts};
  });
  var result={contents:contents,generationConfig:{temperature:isChat?0.6:0.2}};
  if(!isChat)result.generationConfig.responseMimeType="application/json";
  if(system)result.systemInstruction={parts:[{text:system}]};
  return result;
}
function readCloud(provider,data){
  var value;
  if(provider==="openai")value=data&&data.choices&&data.choices[0]&&data.choices[0].message&&data.choices[0].message.content;
  else if(provider==="claude")value=(data&&data.content||[]).filter(function(p){return p.type==="text";}).map(function(p){return p.text||"";}).join("\n");
  else value=(data&&data.candidates&&data.candidates[0]&&data.candidates[0].content&&data.candidates[0].content.parts||[])
    .filter(function(p){return typeof p.text==="string";}).map(function(p){return p.text;}).join("\n");
  if(Array.isArray(value))value=value.filter(function(p){return p&&p.type==="text";}).map(function(p){return p.text||"";}).join("\n");
  if(!value||typeof value!=="string")throw Error(tr("Modellen returnerede intet tekstsvar","Model returned no text"));
  return value;
}
function complete(provider,url,model,messages,kind,images,signal){
  if(kind==="image")return Promise.reject(Error(tr(
    "Billedgenerering kræver foreløbig ForgeShare","Image generation currently requires ForgeShare")));
  if(!known(provider))return Promise.reject(Error("Unknown provider"));
  if(!model)return Promise.reject(Error(tr("Vælg en model først","Choose a model first")));
  try{requireKey(provider);}catch(e){return Promise.reject(e);}
  var target,payload;
  try{
    target=endpoint(provider,url,model,false);
    if(cloud(provider))payload=cloudRequest(provider,model,messages,kind,images||[]);
    else payload=adapters.completionRequest(provider,model,
      adapters.withImageAttachments(provider,messages,images||[]),kind);
  }catch(e){return Promise.reject(e);}
  return requestJson(provider,target,{
    method:"POST",mode:"cors",cache:"no-store",credentials:"omit",redirect:"error",
    headers:headers(provider),body:JSON.stringify(payload),signal:signal
  }).then(function(data){
    var answer=cloud(provider)?readCloud(provider,data):adapters.parseCompletion(provider,data);
    return {text:answer,telemetry:adapters.timingFromResponse(provider,data)||{}};
  });
}
exports.known=known;exports.cloud=cloud;
exports.setKey=setKey;exports.getKey=getKey;exports.forgetKey=forgetKey;exports.requireKey=requireKey;
exports.secretControl=secretControl;exports.listModels=listModels;exports.complete=complete;
exports.endpoint=endpoint;
})();
